actions.script:
const mode = sri.getRenderMode()
const L = (text) => ec.l10n.localize(text)
const items = appItems.map((item) => {
    const out = Object.assign({}, item, {label: String(ec.resource.expand(item.title, '') || item.name)})
    const image = item.image || ''
    if (image && item.imageType == 'icon') {
        if (image.includes(' ') || image.startsWith('fa-')) out.iconClass = image
        else out.iconName = image
    } else if (image) {
        out.iconSrc = item.imageType == 'url-plain' ? image : sri.buildUrl(image).url
    } else {
        out.iconName = 'sym_o_apps'
    }
    return out
})
const claims = (suite, item) => !!suite.component && item.component == suite.component
const suites = appSuites.slice().sort((a, b) => (a.order ?? 100) - (b.order ?? 100))
appSections = []
for (const suite of suites) {
    const suiteItems = items.filter((item) => claims(suite, item))
    if (!suiteItems.length) continue
    const section = {name: suite.name, title: suite.title, items: suiteItems}
    const location = (suite.templates || {})[mode]
    if (location) {
        try {
            const text = ec.resource.template(location, {suite: Object.assign({}, suite, {items: suiteItems})})
            if (mode == 'tui') section.nodes = JSON.parse(text)
            else section.rendered = text
        } catch (e) {
            ec.logger.error('App list template ' + location + ' of suite ' + suite.name + ' failed: ' + e)
        }
    }
    appSections.push(section)
}
const otherItems = items.filter((item) => !suites.some((suite) => claims(suite, item)))
if (otherItems.length) appSections.push({name: 'Other', title: appSections.length ? L('Other Applications') : '', items: otherItems})
for (const uiMode of uiModes) uiMode.current = uiMode.renderMode == mode
if (mode == 'tui') {
    appListNodes = []
    for (const section of appSections) {
        if (section.nodes) { appListNodes.push(...section.nodes); continue }
        if (section.title) appListNodes.push({t: 'text', id: 'AppListSection' + section.name, text: section.title, style: 'h5'})
        for (const item of section.items) appListNodes.push({t: 'link', id: 'AppListApp' + item.name, kind: 'anchor-button', text: item.label, url: String(item.url)})
    }
    appListNodes.push({t: 'text', id: 'AppListUi', text: L('You are using the terminal UI; the same apps are in the browser under /apps.')})
}
